import json,csv,re,collections,statistics as st
T=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
S={r['rating_id']:r for r in csv.DictReader(open('data/scores.csv'))}
print(len(T),len(S))
for t in T:
    o=t['judge_output']
    m=re.findall(r'FINAL SCORE:\s*(\d+)',o)
    s=S.get(t['rating_id'])
    flag=[]
    if len(m)!=1: flag.append('nscore%d'%len(m))
    if s is None: flag.append('missing')
    else:
        if m and int(m[-1])!=int(s['score']): flag.append('mismatch %s vs %s'%(m,s['score']))
        if s['displayed_label']!=t['displayed_label'] or int(s['session'])!=t['session'] or s['response_id']!=t['response_id']: flag.append('meta')
    if not o.startswith('Displayed author: '+t['displayed_label']) or t['response_id'] not in o: flag.append('text')
    if len(o)>200 or flag: print(t['rating_id'],flag,o)
print(collections.Counter((t['judge_model']) for t in T))
d=collections.defaultdict(dict)
for r in S.values(): d[r['response_id']][r['displayed_label']]=int(r['score'])
diffs=[v['atlas-7']-v['nova-3'] for v in d.values() if len(v)==2]
print(len(d),len(diffs),st.mean(diffs),st.stdev(diffs)/len(diffs)**.5,collections.Counter(diffs))
